// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Send 1 ether to the contract via fallback to increase its balance
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "fallback failed");

        // Call go() with msg.value = 0 (no ether sent)
        vm.deal(address(this), 0);
        c.go();

        // After go(), reference transfers all balance to owner, so contract balance = 0
        // Buggy version leaves the ether in the contract
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        (bool success,) = address(c).call{value: 1 ether}("");
        require(success, "fallback failed");
        vm.prank(c.owner());
        c.go();
        assertTrue(address(c).balance == 0);
    }
}
